"""Original ventilator mechanics questions with numerical distractors."""
from qbank_authoring import question,ref
rows=[]
PV=ref('AARC patient-ventilator assessment guideline: 2024','https://pmc.ncbi.nlm.nih.gov/articles/PMC11298231/')
AR=ref('ATS adult ARDS management update: 2024','https://pmc.ncbi.nlm.nih.gov/articles/PMC10870893/')
ES=ref('ESICM ARDS respiratory support guideline: 2023','https://pmc.ncbi.nlm.nih.gov/articles/PMC10354163/')
def q(stem,answer,others,title,principle,details,application,clinical,table,refs,style='direct'):
    rows.append(question(stem,answer,others,title,principle,details,application,clinical,table,refs,style))

q('A man is 175 cm tall. Using PBW = 50 + 0.91 × (height in cm − 152.4), what initial tidal volume is closest to 6 mL/kg PBW?', '420 mL',[
 ('300 mL','This is substantially below six mL/kg for the calculated PBW.'),('600 mL','This exceeds the intended six-mL/kg starting calculation.'),('750 mL','This would markedly exceed a six-mL/kg PBW strategy.')],
 'Calculate lung size from height-based predicted weight','**The calculated PBW is about 70.6 kg, giving roughly 424 mL.**',['Actual body weight is not substituted for PBW in this calculation.','The initial setting is adjusted according to pressure, gas exchange and the clinical situation.'], '**Document tidal volume per PBW.**',['Use lung-protective limits rather than choose volume by obesity or appearance.','Monitor plateau pressure and the patient’s interaction with the ventilator.'],[['PBW','About 70.6 kg'],['6 mL/kg','About 424 mL'],['Closest option','420 mL']],[PV,AR],style='clinical_scenario')

q('A woman weighs 120 kg but has a height-based PBW of 55 kg. What tidal volume corresponds to 6 mL/kg PBW?', '330 mL',[
 ('550 mL','This corresponds to ten mL/kg PBW rather than six.'),('660 mL','This corresponds to twelve mL/kg PBW.'),('720 mL','This incorrectly uses actual weight times six.')],
 'Obesity does not justify actual-weight tidal volumes','**Six times fifty-five gives 330 mL.**',['Lung size tracks height and sex-based PBW more closely than actual mass.','Obesity can alter chest-wall mechanics, which needs separate assessment.'], '**Review pressures and gas exchange without abandoning PBW-based protection.**',['Manage atelectasis and PEEP according to the patient.','Do not assume a high airway pressure always equals the same transpulmonary stress.'],[['PBW','55 kg'],['Actual weight','Not used for this VT calculation'],['VT','330 mL']],[PV,AR],style='clinical_scenario')

q('In a passive patient, tidal volume is 420 mL, plateau pressure 28 cm H2O and total PEEP 10 cm H2O. What is static respiratory-system compliance?', 'About 23 mL/cm H2O',[
 ('15 mL/cm H2O','This approximately divides by plateau without subtracting total PEEP.'),('42 mL/cm H2O','This divides by PEEP rather than the elastic driving pressure.'),('76 mL/cm H2O','This does not follow the stated volume/pressure-gradient calculation.')],
 'Use elastic pressure rather than peak pressure','**Crs = VT / (plateau − total PEEP).**',['Here 420 / 18 is about 23.3 mL/cm H2O.','The measurement assumes an appropriate no-flow plateau and a passive patient.'], '**Interpret reduced compliance as a respiratory-system finding.**',['Lung and chest-wall components can both contribute.','Review pneumothorax, edema, atelectasis and other acute changes when compliance worsens.'],[['Elastic gradient','18 cm H2O'],['Volume','420 mL'],['Compliance','About 23 mL/cm H2O']],[PV],style='clinical_scenario')

q('During constant-flow passive ventilation, peak pressure is 40, plateau pressure 25 cm H2O and inspiratory flow is 0.5 L/s. What is the estimated inspiratory resistance?', '30 cm H2O/L/s',[
 ('15 cm H2O/L/s','This uses the pressure difference without dividing by the flow.'),('50 cm H2O/L/s','This uses plateau pressure rather than the resistive pressure difference.'),('80 cm H2O/L/s','This uses peak pressure without subtracting the elastic plateau component.')],
 'Separate resistive from elastic pressure','**Resistance is approximately (peak − plateau) divided by flow under the stated conditions.**',['The pressure difference is fifteen and fifteen divided by 0.5 is thirty.','Tube and airway resistance both contribute.'], '**Investigate a new resistance rise.**',['Look for secretions, tube kinking, biting or bronchospasm.','Confirm patient passivity and measurement validity.'],[['Peak − plateau','15 cm H2O'],['Flow','0.5 L/s'],['Resistance','30 cm H2O/L/s']],[PV],style='clinical_scenario')

q('Peak airway pressure rises suddenly, but plateau pressure is unchanged during passive volume ventilation. Which mechanism is most likely?', 'Increased airway or endotracheal-tube resistance',[
 ('A major fall in lung compliance alone','A compliance change typically increases plateau as well.'),('A major rise in chest-wall elastance alone','This affects the elastic pressure reflected in plateau.'),('An isolated increase in alveolar elastic pressure at unchanged resistance','The unchanged plateau argues against this as the main new event.')],
 'Peak and plateau answer different mechanical questions','**A widened peak-to-plateau gap points toward resistive loading.**',['Airway/tube obstruction and bronchospasm are common causes.','The interpretation requires a valid no-flow plateau in a passive patient.'], '**Assess the patient and airway promptly.**',['Pass a suction catheter and check tubing and breath sounds as appropriate.','Do not treat the display alone if oxygenation or circulation is deteriorating.'],[['Peak rises/plateau stable','Resistance clue'],['Both rise','Elastic or mixed problem'],['Urgency','Depends on physiological impact']],[PV])

q('A passive ventilated patient has plateau pressure 30 and total PEEP 12 cm H2O. What is the respiratory-system driving pressure?', '18 cm H2O',[
 ('12 cm H2O','This is the total PEEP, not the difference.'),('30 cm H2O','This is plateau pressure without subtraction.'),('42 cm H2O','Driving pressure is not the sum.')],
 'Use total PEEP when intrinsic PEEP is present','**Driving pressure is plateau minus total PEEP.**',['It reflects tidal volume relative to respiratory-system compliance under appropriate passive conditions.','It is a useful assessment variable but not a stand-alone replacement for the complete lung-protective strategy.'], '**Review tidal volume, compliance and patient effort.**',['An airway value is not identical to transpulmonary driving pressure.','Do not interpret a poorly measured plateau as a reliable elastic pressure.'],[['Plateau','30'],['Total PEEP','12'],['Difference','18']],[PV])

q('PaO2 is 80 mmHg while FiO2 is 0.50. What is the PaO2/FiO2 ratio?', '160 mmHg',[
 ('40 mmHg','This multiplies rather than divides.'),('80 mmHg','This ignores the inspired fraction.'),('400 mmHg','This uses an incorrect inspired fraction.')],
 'Use FiO2 as a fraction, not a percentage integer','**Eighty divided by 0.50 equals 160.**',['The ratio describes oxygenation but does not alone establish ARDS.','Timing, imaging, edema cause and support conditions matter for ARDS classification.'], '**Interpret the value in the current ventilatory context.**',['PEEP and FiO2 changes can alter the ratio.','Use trends and the complete syndrome when choosing support.'],[['PaO2','80'],['FiO2','0.50'],['P/F','160']],[AR,ES],style='clinical_scenario')

q('At steady state, PaCO2 is 60 mmHg with alveolar ventilation 6 L/min. Assuming CO2 production is unchanged, what alveolar ventilation would approximately produce PaCO2 45 mmHg?', '8 L/min',[
 ('4.5 L/min','Reducing alveolar ventilation would increase rather than lower PaCO2.'),('6 L/min','Unchanged alveolar ventilation would not produce the intended reduction under the assumptions.'),('10.5 L/min','This is greater than the inverse-proportional calculation requires.')],
 'PaCO2 is inversely proportional to alveolar ventilation at fixed CO2 production','**Required VA = 6 × 60 / 45 = 8 L/min.**',['This is alveolar ventilation, not automatically the same as total minute ventilation.','Dead-space changes, metabolism and nonsteady conditions can alter the relation.'], '**Apply the physiology within lung-protective constraints.**',['Do not increase tidal volume indiscriminately to normalize CO2.','In obstructive disease, raising rate can worsen trapping.'],[['Initial VA','6 L/min'],['CO2 ratio','60/45'],['Required VA','8 L/min']],[PV])

q('PaCO2 is 60 mmHg and mixed expired PCO2 is 30 mmHg. Using the Enghoff modification of the Bohr equation, what is estimated physiologic VD/VT?', '0.50',[
 ('0.25','This underestimates the stated difference relative to PaCO2.'),('0.75','This does not follow the given calculation.'),('1.00','This would require a mixed expired PCO2 near zero under the equation.')],
 'Distinguish mixed expired CO2 from end-tidal CO2','**The estimate is (PaCO2 − mixed expired PCO2) / PaCO2.**',['Here (60 − 30) / 60 equals one half.','The Enghoff estimate also reflects gas-exchange heterogeneity and is not pure anatomical dead space.'], '**Use the measurement to investigate inefficient gas exchange.**',['Changes can reflect pulmonary vascular or parenchymal disease and ventilatory settings.','Do not substitute end-tidal CO2 without understanding the different quantity.'],[['PaCO2','60'],['Mixed expired CO2','30'],['Estimated VD/VT','0.50']],[ref('Physiological dead space in ARDS: original outcome study','https://doi.org/10.1056/NEJMoa012835')])

q('In a passive ventilated patient, expiratory flow has not returned to zero before the next inspiration. Which problem is suggested?', 'Incomplete exhalation with dynamic hyperinflation/auto-PEEP',[
 ('A normal finding proving complete lung emptying','Persistent expiratory flow indicates ongoing emptying.'),('An isolated rise in static chest-wall compliance','This does not explain the truncated exhalation pattern by itself.'),('A leak-free circuit as the only conclusion','Flow timing provides more specific concern for expiratory limitation; leaks also need context.')],
 'Read the waveform before changing the rate','**Insufficient expiratory time can leave trapped gas and intrinsic PEEP.**',['Obstructive disease, high rate and large volumes can contribute.','Active effort can complicate waveform interpretation.'], '**Review resistance and allow sufficient exhalation.**',['Reduce excessive minute-ventilation demand and treat obstruction.','Severe trapping can cause hypotension and make triggering difficult.'],[['Flow not at zero','Incomplete exhalation clue'],['Auto-PEEP','Can impair hemodynamics/triggering'],['Strategy','More expiratory time and cause treatment']],[PV])

q('An end-expiratory hold in a passive patient shows total PEEP 15 cm H2O while set PEEP is 8. What is measured intrinsic PEEP?', '7 cm H2O',[
 ('8 cm H2O','This is the set external PEEP.'),('15 cm H2O','This is total PEEP, not the intrinsic component.'),('23 cm H2O','The intrinsic component is the difference, not the sum.')],
 'Distinguish external and trapped-pressure components','**Intrinsic PEEP is total PEEP minus set PEEP under the measurement conditions.**',['Passive measurement requires an appropriate expiratory hold.','Regional gas trapping and airway closure can make the measured value an incomplete description.'], '**Investigate the cause and physiological impact.**',['Treat bronchospasm, secretions and excessive expiratory truncation.','Assess blood pressure and patient-ventilator triggering.'],[['Total','15'],['External','8'],['Intrinsic','7']],[PV],style='clinical_scenario')

q('At unchanged pressure-control settings, delivered tidal volume falls. Which interpretation is most accurate?', 'Compliance, resistance, effort or circuit conditions may have changed and must be assessed',[
 ('Pressure control guarantees a fixed tidal volume','Delivered volume depends on the respiratory system and patient interaction.'),('The fall proves improved lung compliance','Improved compliance would generally increase volume at the same pressure under otherwise similar conditions.'),('The ventilator mode makes patient assessment unnecessary','A change in delivered ventilation can signal deterioration or equipment problems.')],
 'Know what the ventilator controls and what varies','**Pressure control sets an inspiratory pressure pattern rather than guaranteeing volume.**',['Changing compliance, resistance or inspiratory time affects delivered volume.','Leaks and patient effort can also alter measurements.'], '**Check the patient, circuit, airway and gas exchange.**',['Do not simply raise pressure without identifying the cause.','Continue to monitor lung-protective tidal volume and pressure exposure.'],[['Set pressure','Controlled variable'],['VT','Can vary'],['New fall','Requires physiological and technical review']],[PV])

if __name__=='__main__':print(f'Mechanical ventilation draft: {len(rows)} questions')
